using System.Reflection;
using ET;
using ET.Server;
var opts=args.Select(a=>a.Split('=',2)).ToDictionary(a=>a[0],a=>a.Length>1?a[1]:"");
if(opts.GetValueOrDefault("testClass")!="FullRouteOnline"||opts.GetValueOrDefault("includePassingTests")!="true"||!int.TryParse(opts.GetValueOrDefault("maxTests"),out int max)||max<1)throw new ArgumentException("Explicit FullRouteOnline filter required");
var config=ServerConfig.CreateForValidation("OnlineLocal",n=>File.ReadAllBytes(Path.Combine("Server/GameServer/Config/Luban",n+".bytes")));
World.Instance.AddSingleton(config);World.Instance.AddSingleton<TimeInfo>();World.Instance.AddSingleton<ObjectPool>();
object ManagerCall(string name,params object[] values)=>typeof(OnlineArcadeRunManagerSystem).GetMethod(name,BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public)!.Invoke(null,values)!;
object Call(string name,params object[] values)=>typeof(OnlineArcadeRunActorSystem).GetMethod(name,BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public)!.Invoke(null,values)!;
OnlineArcadeRunRecord Record(int ordinal=1,int map=1)=>new(){RunId=1,RoomId=2,Revision=1,IsCasualRoute=true,ArenaConfigNumber=map,NextArena=ordinal,ConfigFingerprint=config.ArcadeRule.ConfigFingerprint,Players=new(){new(){PlayerId=1,Lives=3,Ready=true,WeaponId="arcade.weapon.basic"},new(){PlayerId=2,Lives=3,Ready=true,WeaponId="arcade.weapon.basic"}}};
OnlineArcadeRunActor ContentActor(int special=0,int evt=0){var row=config.Tables.TbArcadeRoundLayout.DataList.First(p=>special>0?p.SpecialKind==special:p.EventKind==evt);var r=Record(2,row.ArenaConfigNumber);var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);Call("PrepareWave",b,config.Tables.TbArcadeArena.Get(row.ArenaConfigNumber),row.RoundNumber-1);return new(){Record=r,Battle=b};}
var tests=new (string,Action)[]{
 ("Barrel explosion damages each target by its maximum health",()=>{
     var a=ContentActor(special:1);var b=a.Battle;
     var carrier=new OnlineArcadeEnemyRuntime{RuntimeId=101,SpecialKind=1,PositionX=0,PositionZ=0,Damage=99,LastDamagePlayerId=1};
     var small=new OnlineArcadeEnemyRuntime{RuntimeId=102,PositionX=1,CurrentHealth=100,MaxHealth=100};
     var large=new OnlineArcadeEnemyRuntime{RuntimeId=103,PositionX=2,CurrentHealth=50,MaxHealth=200};
     var outside=new OnlineArcadeEnemyRuntime{RuntimeId=104,PositionX=5,CurrentHealth=100,MaxHealth=100};
     b.Enemies[101]=carrier;b.Enemies[102]=small;b.Enemies[103]=large;b.Enemies[104]=outside;
     b.EnemyIterationIds.AddRange(b.Enemies.Keys);
     Call("KillEnemy",a,b,carrier,false);
     Require(small.CurrentHealth==88,"100 maximum health must lose 12, independent of carrier damage");
     Require(large.CurrentHealth==26,"200 maximum health must lose 24, independent of current health");
     Require(outside.CurrentHealth==100,"explosion damaged target outside radius");
     Require(small.LastDamagePlayerId==1&&large.LastDamagePlayerId==1,"explosion lost damage attribution");
 }),
 ("Barrel danger damages players by maximum health and expires at 1.2 seconds",()=>{
     var a=ContentActor(special:1);var b=a.Battle;
     // 避开本轮落桶事件，只观察载体死亡产生的独立危险区域。
     b.ContentClock.Advance(2,false);
     foreach(var player in b.Players.Values){player.PositionX=0;player.PositionZ=0;player.MaxHealth=100;player.CurrentHealth=100;player.InvulnerabilitySeconds=0;}
     b.Players[2].MaxHealth=200;b.Players[2].CurrentHealth=200;
     Call("SpawnContentDeathZone",a,b,new OnlineArcadeEnemyRuntime{RuntimeId=101,SpecialKind=1,PositionX=0,PositionZ=0});
     Call("TickRoundContent",a,b,.01f);
     Require(b.Players[1].CurrentHealth==88&&b.Players[2].CurrentHealth==176,"danger must deal 12 percent of each player's maximum health");
     Call("TickRoundContent",a,b,1.18f);Require(b.DeathZones.Count==1,"danger expired before 1.2 seconds");
     foreach(var player in b.Players.Values)player.InvulnerabilitySeconds=0;
     Call("TickRoundContent",a,b,.02f);
     Require(b.DeathZones.Count==0,"danger survived past 1.2 seconds");
     Require(b.Players[1].CurrentHealth==88&&b.Players[2].CurrentHealth==176,"expired danger still damaged players");
 }),
 ("Clear requires explicit round exit even after long wait",()=>{var record=Record();var b=OnlineArcadeRunActorSystem.PrepareBattle(record,false);var a=new OnlineArcadeRunActor{Record=record,Battle=b};b.SpawnQueueIndex=b.SpawnQueue.Count;Call("TryAdvanceWave",a,b,0f);Call("TryAdvanceWave",a,b,100f);Require(b.WaveIndex==0&&b.AwaitingExit,"auto-advanced ordinary round");}),
 ("Readiness gate exists before simulation",()=>{var b=OnlineArcadeRunActorSystem.PrepareBattle(Record(),false);Require(typeof(OnlineArcadeRunActorSystem).GetMethod("RoundPlayersReady",BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public)!=null,"missing readiness gate");Require(!(bool)Call("RoundPlayersReady",b),"unloaded players simulated");}),
 ("Every route round resolves an explicit layout",()=>{foreach(int map in Enumerable.Range(1,20))foreach(int round in Enumerable.Range(0,4)){var b=OnlineArcadeRunActorSystem.PrepareBattle(Record(2,map),false);Call("PrepareWave",b,config.Tables.TbArcadeArena.Get(map),round);var field=typeof(OnlineArcadeBattleRuntime).GetField("RoundLayout");Require(field!=null&&field.GetValue(b)!=null,"missing map "+map+" round "+round);b.NextSpawnAt=0;Call("TrySpawnEnemy",b,TimeInfo.Instance.ServerNow());Require(b.Enemies.Values.All(e=>string.IsNullOrEmpty(e.BossId)&&e.ContentBossKind==0),"ordinary round spawned dedicated boss");}}),
 ("Stale readiness cannot unlock current map",()=>{var r=Record();var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);var a=new OnlineArcadeRunActor{Record=r,Battle=b};bool rejected=false;try{a.SubmitInput(1,1,1,0,0,0,1,false,false,false,b.RoundGeneration-1,true);}catch(RpcException){rejected=true;}Require(rejected&&b.Players[1].ReadyRoundGeneration==0,"stale ack accepted");a.SubmitInput(1,1,2,0,0,0,1,false,false,false,b.RoundGeneration,true);Require(!(bool)Call("RoundPlayersReady",b),"one member unlocked clock");a.SubmitInput(2,1,1,0,0,0,1,false,false,false,b.RoundGeneration,true);Require((bool)Call("RoundPlayersReady",b),"all members never unlocked");}),
 ("Loading freezes effects drops and event clocks",()=>{var r=Record();var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);var a=new OnlineArcadeRunActor{Record=r,Battle=b};b.Players[1].TemporaryWeaponSeconds=9;b.Drops[1]=new(){RuntimeId=1,RemainingSeconds=4};long now=b.LastTickAt;a.TickBattle(now+1000);Require(b.Players[1].TemporaryWeaponSeconds==9&&b.Drops[1].RemainingSeconds==4&&b.ContentClock.Elapsed==0,"loading consumed timers");}),
 ("Simultaneous route confirmations choose lowest player once",()=>{var r=Record();var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);Call("PrepareWave",b,config.Tables.TbArcadeArena.Get(1),3);b.AwaitingExit=true;var layout=b.RoundLayout;foreach(var p in b.Players.Values){p.PositionZ=layout.ExitY;p.PositionX=layout.ExitX+(p.PlayerId==1?-.5f:.5f)*layout.ExitSpacing;p.ConfirmedExitTarget=p.PlayerId==1?2:3;}Require((bool)Call("TickExit",b)&&b.SelectedExitConfigNumber==2,"arbitration changed");Require(!(bool)Call("TickExit",b)&&b.SelectedExitConfigNumber==2,"duplicate committed twice");}),
 ("Failed round save preserves all members then retry publishes together",()=>{string folder=Path.GetFullPath(Path.Combine("Tools/ArcadeFullRouteOnlineChecks/.test-output",Guid.NewGuid().ToString("N")));Directory.CreateDirectory(folder);try{var r=Record(2,2);r.Phase=OnlineArcadeRunPhase.SafeCheckpoint;r.CreatedAtUtc=r.UpdatedAtUtc=DateTime.UtcNow.ToString("O");var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);var a=new OnlineArcadeRunActor{Record=r,CommittedRecord=OnlineArcadeRunManagerSystem.Clone(r),Battle=b};typeof(Entity).GetProperty("InstanceId")!.SetValue(a,1L);var m=new OnlineArcadeRunManagerComponent{StorePath=Path.Combine(folder,"runs.json")};m.Runs[1]=a;ManagerCall("CommitWithCandidate",m,r,1L);string before=File.ReadAllText(m.StorePath);b.RoundTransitionPending=true;var crate=b.Crates.Values.First();int crateId=crate.Definition.Id;crate.Damage(13,true);int partialHealth=crate.Health;b.Players[1].CurrentHealth=37;b.Players[2].CurrentHealth=61;b.Players[1].InvulnerabilitySeconds=4;b.Players[1].DashSeconds=.7f;b.Players[1].FireCooldownSeconds=.3f;b.Players[1].TemporaryWeaponId="arcade.weapon.rapid";b.Players[1].TemporaryWeaponSeconds=7;b.Players[1].Powerups[ArcadePowerupBehavior.Boots]=new(){ProductId="arcade.powerup.boots",Behavior=ArcadePowerupBehavior.Boots,RemainingSeconds=11,Magnitude=2};m.RemainingFailSaveCount=1;Require(!(bool)ManagerCall("TryCommitRoundTransition",m,a),"injected failure ignored");Require(ReferenceEquals(a.Battle,b)&&a.Record.RoundNumber==1&&File.ReadAllText(m.StorePath)==before,"failed save published half team");Require((bool)ManagerCall("TryCommitRoundTransition",m,a),"retry rejected");Require(a.Battle.WaveIndex==1&&a.Battle.RoundGeneration==2&&a.Battle.Players[1].CurrentHealth==37&&a.Battle.Players[2].CurrentHealth==61,"retry lost member snapshot");Require(a.Battle.Players[1].TemporaryWeaponSeconds==7&&a.Battle.Players[1].Powerups[ArcadePowerupBehavior.Boots].RemainingSeconds==11,"effects refreshed or lost");var restored=System.Text.Json.JsonSerializer.Deserialize<OnlineArcadeRunStoreSnapshot>(File.ReadAllText(m.StorePath))!.Runs.Single();Require(restored.Players[0].RoundPowerups.Single().RemainingSeconds==11,"effect remaining amount not serialized");var resumed=OnlineArcadeRunActorSystem.PrepareBattle(restored,false);Require(resumed.WaveIndex==1&&resumed.Players[1].CurrentHealth==37,"restart resumed wrong round");Require(resumed.Crates[crateId].Health==partialHealth,"surviving crate restored full health");Require(resumed.Players[1].InvulnerabilitySeconds==4&&resumed.Players[1].DashSeconds==.7f&&resumed.Players[1].FireCooldownSeconds==.3f,"logical protection or cooldown lost at round node");}finally{Directory.Delete(folder,true);}}),
 ("Mannequin hit freeze survives ordinary ally aura scan",()=>{var r=Record(2,15);var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);var a=new OnlineArcadeRunActor{Record=r,Battle=b};var e=new OnlineArcadeEnemyRuntime{RuntimeId=1,SpecialKind=3,PositionX=0,PositionZ=4,MoveSpeed=3,CurrentHealth=50,MaxHealth=50,LastContentHitAt=0};b.Enemies[1]=e;b.Enemies[2]=new(){RuntimeId=2,PositionX=10,PositionZ=10,CurrentHealth=50,MaxHealth=50};Call("TickEnemies",a,b,.1f);Require(e.PositionX==0&&e.PositionZ==4,"aura scan unfreezes mannequin");}),
 ("Dedicated bosses survive bombs and only final boss marks total victory",()=>{foreach(int map in new[]{4,9,16,20}){var r=Record(map==20?10:3,map);var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);Call("PrepareWave",b,config.Tables.TbArcadeArena.Get(map),3);Call("PrepareRoundBoss",b);Call("TrySpawnEnemy",b,TimeInfo.Instance.ServerNow());var e=b.Enemies.Values.Single();Require(e.ContentBossKind>0&&b.WaveIndex==3,"dedicated boss absent");var a=new OnlineArcadeRunActor{Record=r,Battle=b};r.Players[0].Bombs=1;Call("UseBomb",a,b,b.Players[1]);Require(b.Enemies.ContainsKey(e.RuntimeId),"bomb erased dedicated boss");Call("KillEnemy",a,b,e,true);Require(b.RoundBossDefeated&&b.AwaitingExit&&!b.ArenaCompletionReady,"boss skipped exit confirmation");Require(b.FinalBossDefeated==(map==20),"non-final boss marked total victory");}}),
 ("Content clock freezes during exits respawn and all-member treasure",()=>{for(int mode=0;mode<3;mode++){var r=Record(4,6);var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);var a=new OnlineArcadeRunActor{Record=r,Battle=b};b.ContentClock.Advance(b.RoundLayout.EventWarning+.1f,false);if(mode==0)b.AwaitingExit=true;else if(mode==1)b.Players[1].RespawnSeconds=3;else foreach(var player in b.Players.Values)player.InTreasureRoom=true;double before=b.ContentClock.Elapsed;int hp=b.Players[1].CurrentHealth;Call("TickRoundContent",a,b,100f);Require(b.ContentClock.Elapsed==before&&b.Players[1].CurrentHealth==hp,"inactive phase consumed content mode "+mode);}}),
 ("Island constraining still respects current round obstacles",()=>{var b=OnlineArcadeRunActorSystem.PrepareBattle(Record(),false);var obstacles=(System.Collections.Generic.IReadOnlyList<ArcadeObstacleConfig>)Call("EffectiveObstacles",b);var o=obstacles.First();object[] values={o.CenterX,o.CenterY,0f,0f,.55f,config.ArcadeRule,obstacles,Call("IslandFor",b)};typeof(OnlineArcadeRunActorSystem).GetMethod("ResolvePosition",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,values);Require(!(bool)Call("InsideObstacle",(float)values[0],(float)values[1],.55f,obstacles),"island path ignored layout obstacle");}),
 ("Mannequin requires separated three hits and drop armor warns safely",()=>{var a=ContentActor(special:3);var b=a.Battle;var e=new OnlineArcadeEnemyRuntime{RuntimeId=1,SpecialKind=3,CurrentHealth=100,MaxHealth=100};Call("DamageEnemy",b,e,1);int first=e.CurrentHealth;Require(first>1&&first<100,"mannequin ordinary damage instead of first stage");Call("DamageEnemy",b,e,10000);Require(e.CurrentHealth==first,"freeze accepted repeated hit");e.ContentElapsed+=b.RoundLayout.SkillWarning+.1f;Call("DamageEnemy",b,e,1);Require(e.CurrentHealth>0&&e.CurrentHealth<first,"second mannequin stage");e.ContentElapsed+=b.RoundLayout.SkillWarning+.1f;Call("DamageEnemy",b,e,1);Require(e.CurrentHealth==0,"third mannequin hit did not kill");a=ContentActor(special:13);b=a.Battle;e=new(){RuntimeId=1,SpecialKind=13,CurrentHealth=100,MaxHealth=100};Call("DamageEnemy",b,e,100);Require(e.CurrentHealth==100,"airdrop damaged before landing");}),
 ("Elder evolves each nearby ally once",()=>{var a=ContentActor(special:12);var b=a.Battle;var e=new OnlineArcadeEnemyRuntime{RuntimeId=1,SpecialKind=12,PositionX=0,PositionZ=0,ContentElapsed=b.RoundLayout.SkillWarning+.1f};var ally=new OnlineArcadeEnemyRuntime{RuntimeId=2,CurrentHealth=100,MaxHealth=100,PositionX=0,PositionZ=0};b.Enemies[1]=e;b.Enemies[2]=ally;Call("TickSpecialAttack",a,b,e,b.Players[1]);Require(ally.MaxHealth>100&&ally.CurrentHealth==ally.MaxHealth,"elder did not evolve ally");int health=ally.MaxHealth;e.ContentElapsed+=b.RoundLayout.SkillPeriod;Call("TickSpecialAttack",a,b,e,b.Players[1]);Require(ally.MaxHealth==health,"elder multiplied same ally again");}),
 ("Storm consumes drops without award and ghost contact is lethal",()=>{var a=ContentActor(evt:6);var b=a.Battle;b.ContentClock.Advance(b.RoundLayout.EventWarning+.1f,false);FirepowerLoop.Arcade.ArcadeRoundContentRules.EventCenter(6,b.ContentClock.Elapsed,0,0,b.RoundLayout.EventRadius*2,b.RoundLayout.EventMoveSpeed,out float x,out float y);b.Drops[1]=new(){RuntimeId=1,PositionX=x,PositionZ=y};Call("TickRoundContent",a,b,.01f);Require(!b.Drops.ContainsKey(1)&&b.SupplyPickups.Count==0,"storm did not consume without reward");a=ContentActor(evt:2);b=a.Battle;b.ContentClock.Advance(b.RoundLayout.EventWarning+.1f,false);FirepowerLoop.Arcade.ArcadeRoundContentRules.EventCenter(2,b.ContentClock.Elapsed+.01,0,0,b.RoundLayout.EventRadius*2,b.RoundLayout.EventMoveSpeed,out x,out y);b.Players[1].PositionX=x;b.Players[1].PositionZ=y;Call("TickRoundContent",a,b,.01f);Require(!b.Players[1].Alive,"ghost did not use lethal contact");}),
