 ("Ranged specials own attacks without legacy double fire",()=>{var source=config.Tables.TbEnemy.DataList.First(e=>e.AttackKind==EnemyAttackKind.Projectile);foreach(int kind in new[]{8,9,11,16,17}){var a=ContentActor(special:kind);var b=a.Battle;foreach(var player in b.Players.Values){player.PositionX=0;player.PositionZ=0;}var e=new OnlineArcadeEnemyRuntime{RuntimeId=1,SpecialKind=kind,PositionX=0,PositionZ=0,CurrentHealth=100,MaxHealth=100,Damage=30,AttackCooldownSeconds=0,AttackIntervalSeconds=1,AttackKind=EnemyAttackKind.Projectile,AttackRange=100,ProjectileConfigId=source.ProjectileConfigId,ContentElapsed=b.RoundLayout.SkillWarning+.1f};b.Enemies[1]=e;Call("TickEnemies",a,b,.01f);Require(b.Projectiles.Count==(kind==8||kind==9||kind==17?1:0),"legacy duplicated special attack kind "+kind);}}),
 ("Mega boss actually warns fires four rays eight shots and two reinforcements",()=>{var a=ContentActor(special:11);var b=a.Battle;Call("PrepareWave",b,config.Tables.TbArcadeArena.Get(16),3);Call("PrepareRoundBoss",b);Call("TrySpawnEnemy",b,TimeInfo.Instance.ServerNow());var e=b.Enemies.Values.Single();b.Players[1].PositionX=0;b.Players[1].PositionZ=10;e.PositionX=e.PositionZ=0;e.ContentElapsed=.1;Call("TickContentBoss",a,b,e,b.Players[1],.01f);Require(b.DeathZones.Count(z=>z.Segment&&z.WarningRemaining>0)==4,"mega missing four warning lines");e.ContentElapsed=b.RoundLayout.SkillWarning+.1f;Call("TickContentBoss",a,b,e,b.Players[1],.01f);Require(b.DeathZones.Count(z=>z.Segment&&z.DamageRatio>0)==4,"mega missing four live rays");e.ContentElapsed=b.RoundLayout.SkillPeriod+b.RoundLayout.SkillWarning+.1f;Call("TickContentBoss",a,b,e,b.Players[1],.01f);Require(b.Projectiles.Count==8,"mega missing eight directional shots");int before=b.Enemies.Count;e.ContentElapsed=b.RoundLayout.SkillPeriod*2+b.RoundLayout.SkillWarning+.1f;Call("TickContentBoss",a,b,e,b.Players[1],.01f);Require(b.Enemies.Count-before==2,"mega reinforcement count differs from round magnitude 2.5 rounded to 2");}),
 ("Guardian fan and ZRex fields preserve dedicated attack shapes",()=>{foreach(int map in new[]{4,9}){var r=Record(3,map);var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);Call("PrepareWave",b,config.Tables.TbArcadeArena.Get(map),3);Call("PrepareRoundBoss",b);Call("TrySpawnEnemy",b,TimeInfo.Instance.ServerNow());var a=new OnlineArcadeRunActor{Record=r,Battle=b};var e=b.Enemies.Values.Single();e.ContentElapsed=b.RoundLayout.SkillPeriod+.1f;b.Players[1].PositionX=0;b.Players[1].PositionZ=10;Call("TickContentBoss",a,b,e,b.Players[1],.01f);b.Players[1].PositionZ=15;e.ContentElapsed=b.RoundLayout.SkillPeriod+b.RoundLayout.SkillWarning+.1f;Call("TickContentBoss",a,b,e,b.Players[1],.01f);if(map==4)Require(b.Projectiles.Count==5,"guardian fan is not five shots");else{Require(b.DeathZones.Any(z=>z.Kind==1&&z.DamageRatio>0&&z.Y==10),"ZRex lost locked eruption target");e.ContentElapsed=b.RoundLayout.SkillPeriod*2+b.RoundLayout.SkillWarning+.1f;Call("TickContentBoss",a,b,e,b.Players[1],.01f);Require(b.DeathZones.Any(z=>z.Kind==8&&z.DamageRatio>0),"ZRex missing spore field");}}}),
 ("Papaback actual chase charge and ray use original boss configuration",()=>{var r=Record(10,20);var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);Call("PrepareWave",b,config.Tables.TbArcadeArena.Get(20),3);Call("PrepareRoundBoss",b);Call("TrySpawnEnemy",b,TimeInfo.Instance.ServerNow());var a=new OnlineArcadeRunActor{Record=r,Battle=b};var e=b.Enemies.Values.Single();foreach(var p in b.Players.Values){p.PositionX=0;p.PositionZ=10;}e.PositionX=e.PositionZ=0;e.BossSkillCooldownSeconds=e.BossRayCooldownSeconds=100;Call("TickEnemies",a,b,.1f);Require(e.PositionZ>0,"Papaback legacy chase absent between skills");e.PositionX=e.PositionZ=0;e.BossSkillCooldownSeconds=0;e.BossRayCooldownSeconds=100;Call("TickEnemies",a,b,.01f);Require(e.BossId=="arcade.boss.final"&&e.BossPhase==OnlineArcadeBossPhase.Telegraph&&e.BossPhaseSeconds>.8f,"Papaback did not enter configured charge telegraph");Call("TickEnemies",a,b,1f);Require(e.BossPhase==OnlineArcadeBossPhase.Charging,"Papaback never charged");b.Players[1].PositionZ=.1f;int hp=b.Players[1].CurrentHealth;Call("TickEnemies",a,b,.1f);Require(e.PositionZ>0&&b.Players[1].CurrentHealth<hp,"configured charge did not sweep hit");e.BossPhase=OnlineArcadeBossPhase.None;e.BossRayCooldownSeconds=0;e.BossSkillCooldownSeconds=100;Call("TickEnemies",a,b,.01f);Require(e.BossPhase==OnlineArcadeBossPhase.RayTelegraph,"Papaback ray telegraph absent");Call("TickEnemies",a,b,1f);Require(b.Projectiles.Count==1&&Math.Abs(Math.Sqrt(b.Projectiles.Values.Single().VelocityX*b.Projectiles.Values.Single().VelocityX+b.Projectiles.Values.Single().VelocityZ*b.Projectiles.Values.Single().VelocityZ)-10)<.01,"Papaback configured ray not fired");}),
