if(tests.Length>max)throw new InvalidOperationException("Test limit exceeded");int failures=0;
foreach(var(name,test)in tests)try{test();Console.WriteLine("PASS FullRouteOnline."+name);}catch(Exception ex){failures++;Console.WriteLine("FAIL FullRouteOnline."+name+": "+(ex.InnerException??ex).ToString());}
Console.WriteLine($"{tests.Length-failures}/{tests.Length} passed");Environment.ExitCode=failures==0?0:1;
static void Require(bool condition,string reason){if(!condition)throw new InvalidOperationException(reason);}
